import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns

def task_func(array, features=None, seed=None):
    if not isinstance(array, np.ndarray) or array.ndim != 2:
        raise ValueError("array must be a 2-dimensional numpy array")
    if array.size == 0:
        raise ValueError("array cannot be empty")

    if features is not None:
        if len(features) != array.shape[1]:
            raise ValueError("features must match the number of columns in array")
    else:
        features = [str(i+1) for i in range(array.shape[1])]

    if seed is not None:
        rng = np.random.default_rng(seed)
        shuffled_indices = rng.permutation(array.shape[1])
    else:
        shuffled_indices = np.random.permutation(array.shape[1])

    shuffled_array = array[:, shuffled_indices]
    features = [features[i] for i in shuffled_indices]

    plt.figure(figsize=(10, 8))
    ax = sns.heatmap(shuffled_array, cmap="viridis", xticklabels=features, yticklabels=False, cbar=True)
    plt.show()
    return ax

