import itertools
import statistics
from collections import Counter

def task_func(elements, subset_size):
    if subset_size <= 0 or subset_size > len(elements):
        return {"mean": 0.0, "median": 0.0, "mode": []}

    subsets = itertools.combinations(elements, subset_size)
    subset_sums = [sum(subset) for subset in subsets]

    mean = statistics.mean(subset_sums)
    median = statistics.median(subset_sums)

    if len(subset_sums) == 0:
        mode = []
    else:
        sum_counts = Counter(subset_sums)
        max_count = max(sum_counts.values())
        mode = [s for s, count in sum_counts.items() if count == max_count]

    return {"mean": mean, "median": median, "mode": mode}

