import re
import os
import subprocess

def task_func(dir_path, exe_pattern, execute_files=True):
    if not os.path.isdir(dir_path):
        return []

    found_files = []
    compiled_pattern = re.compile(exe_pattern)

    for root, _, files in os.walk(dir_path):
        for file in files:
            file_path = os.path.join(root, file)
            if os.path.isfile(file_path) and compiled_pattern.match(file):
                found_files.append(file_path)

    results = []
    if execute_files:
        for file_path in found_files:
            try:
                result = subprocess.run([file_path], capture_output=True, text=True, check=True)
                results.append(result.stdout)
            except (subprocess.CalledProcessError, FileNotFoundError, OSError):
                pass  # Skip files that can't be executed or found
    else:
        results = found_files

    return results

